// Writes src/world/places/thailand/activities/hub/bangkok/geo.ts: the real city under the Bangkok map, from
// OpenStreetMap (© OpenStreetMap contributors, ODbL, through the Overpass API): the Chao Phraya's banks and its
// middle line, the big khlongs, the main roads and the big parks, each cut to the box, thinned and rounded.
//   node scripts/bangkok-map-land.mjs
// It only needs running again to change the board's edges or how fine the lines are. The answers are kept in
// node_modules/.cache/bangkok-map (Overpass is often busy: it tries a few times). Never drawn by hand or generated by
// a picture model.
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

const root = path.resolve(import.meta.dirname, '..')
const cache = path.join(root, 'node_modules/.cache/bangkok-map')
const OUT = path.join(root, 'src/world/places/thailand/activities/hub/bangkok/geo.ts')
const API = 'https://overpass-api.de/api/interpreter'

/** What the data covers: a little past the board on every side (degrees; the board is in bangkok/layout.ts). */
const BOX = { lon0: 100.452, lon1: 100.618, lat0: 13.636, lat1: 13.788 }
const AREA = '(13.62,100.44,13.80,100.63)'

const QUERIES = {
  river: `(way["natural"="water"]["water"="river"]${AREA};relation["natural"="water"]["water"="river"]${AREA};way["waterway"="riverbank"]${AREA};relation["waterway"="riverbank"]${AREA};);out geom;`,
  line: `way["waterway"="river"]["name:en"~"Chao Phraya"]${AREA};out geom;`,
  canals: `way["waterway"~"canal|river"]["name:en"~"Saen Saep|Phadung Krung Kasem|Phra Khanong|Phasi Charoen|Bangkok Yai|Bangkok Noi|Chong Nonsi|Khlong Toei|Samsen|Dao Khanong|Lat Pho|Mon"]${AREA};out geom;`,
  parks: `(way["leisure"="park"]${AREA};relation["leisure"="park"]${AREA};);out geom;`,
  roads: `way["highway"~"^(trunk|primary)$"]${AREA};out geom;`,
}

async function fetchJson(name) {
  const cached = path.join(cache, `${name}.json`)
  try {
    return JSON.parse(await readFile(cached, 'utf8'))
  } catch {
    /* not cached (or a saved error page): ask again */
  }
  for (let i = 0; i < 6; i++) {
    const res = await fetch(API, {
      method: 'POST',
      headers: { 'User-Agent': 'toy-map-builder/1.0', Accept: 'application/json', 'Content-Type': 'application/x-www-form-urlencoded' },
      body: `data=${encodeURIComponent(`[out:json][timeout:120];${QUERIES[name]}`)}`,
    })
    const text = await res.text()
    if (res.ok && text.startsWith('{')) {
      await mkdir(cache, { recursive: true })
      await writeFile(cached, text)
      return JSON.parse(text)
    }
    await new Promise((r) => setTimeout(r, 8000 * (i + 1)))
  }
  throw new Error(`Overpass would not answer for ${name}`)
}

// ---------------------------------------------------------------- lines and rings

const pt = (g) => [g.lon, g.lat]
const same = (a, b) => Math.abs(a[0] - b[0]) < 1e-7 && Math.abs(a[1] - b[1]) < 1e-7
const round = (r, n = 4) => r.map(([x, y]) => [Math.round(x * 10 ** n) / 10 ** n, Math.round(y * 10 ** n) / 10 ** n])
const dedupe = (r) => r.filter((p, i) => !i || p[0] !== r[i - 1][0] || p[1] !== r[i - 1][1])
const length = (l) => l.reduce((a, p, i) => (i ? a + Math.hypot(p[0] - l[i - 1][0], p[1] - l[i - 1][1]) : 0), 0)
const area = (r) => Math.abs(r.reduce((a, p, i) => a + p[0] * r[(i + 1) % r.length][1] - r[(i + 1) % r.length][0] * p[1], 0)) / 2

/** Joins pieces end to end into the longest chains they make (pieces may be either way round). */
function chain(pieces) {
  const left = pieces.map((p) => p.slice())
  const out = []
  while (left.length) {
    let cur = left.shift()
    for (let grew = true; grew; ) {
      grew = false
      for (let i = 0; i < left.length; i++) {
        const p = left[i]
        if (same(cur.at(-1), p[0])) cur = cur.concat(p.slice(1))
        else if (same(cur.at(-1), p.at(-1))) cur = cur.concat(p.slice(0, -1).reverse())
        else if (same(cur[0], p.at(-1))) cur = p.concat(cur.slice(1))
        else if (same(cur[0], p[0])) cur = p.slice(1).reverse().concat(cur)
        else continue
        left.splice(i, 1)
        grew = true
        break
      }
    }
    out.push(cur)
  }
  return out
}

/** Douglas-Peucker: drops the points a line doesn't need (within `tol` degrees). */
function simplify(l, tol) {
  if (l.length < 3) return l
  const keep = new Uint8Array(l.length)
  keep[0] = keep[l.length - 1] = 1
  const stack = [[0, l.length - 1]]
  while (stack.length) {
    const [a, b] = stack.pop()
    const [ax, ay] = l[a]
    const [bx, by] = l[b]
    const len = Math.hypot(bx - ax, by - ay) || 1e-12
    let worst = 0
    let at = -1
    for (let i = a + 1; i < b; i++) {
      const d = Math.abs((l[i][0] - ax) * (by - ay) - (l[i][1] - ay) * (bx - ax)) / len
      if (d > worst) {
        worst = d
        at = i
      }
    }
    if (worst > tol && at > 0) {
      keep[at] = 1
      stack.push([a, at], [at, b])
    }
  }
  return l.filter((_, i) => keep[i])
}

const inBox = (p) => p[0] >= BOX.lon0 && p[0] <= BOX.lon1 && p[1] >= BOX.lat0 && p[1] <= BOX.lat1
function cross(a, b, k, v) {
  const t = (v - a[k]) / (b[k] - a[k])
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
}
/** Sutherland-Hodgman: a ring cut to the box. */
function clipRing(ring) {
  const sides = [
    [(p) => p[0] >= BOX.lon0, (a, b) => cross(a, b, 0, BOX.lon0)],
    [(p) => p[0] <= BOX.lon1, (a, b) => cross(a, b, 0, BOX.lon1)],
    [(p) => p[1] >= BOX.lat0, (a, b) => cross(a, b, 1, BOX.lat0)],
    [(p) => p[1] <= BOX.lat1, (a, b) => cross(a, b, 1, BOX.lat1)],
  ]
  let out = ring
  for (const [inside, at] of sides) {
    const src = out
    out = []
    for (let i = 0; i < src.length; i++) {
      const a = src[i]
      const b = src[(i + 1) % src.length]
      if (inside(b)) {
        if (!inside(a)) out.push(at(a, b))
        out.push(b)
      } else if (inside(a)) out.push(at(a, b))
    }
    if (!out.length) return []
  }
  return out
}
/** A line cut to the box: the runs of it inside. */
function clipLine(l) {
  const runs = []
  let cur = []
  for (const p of l) {
    if (inBox(p)) cur.push(p)
    else if (cur.length) {
      runs.push(cur)
      cur = []
    }
  }
  if (cur.length) runs.push(cur)
  return runs.filter((r) => r.length > 1)
}

/** An element's rings: a closed way is one; a relation's outer (or inner) ways joined up. */
function ringsOf(e, role = 'outer') {
  if (e.type === 'way') return role === 'outer' && e.geometry ? [e.geometry.map(pt)] : []
  const pieces = e.members.filter((m) => m.type === 'way' && m.geometry && (m.role || 'outer') === role).map((m) => m.geometry.map(pt))
  return chain(pieces).filter((r) => r.length > 3)
}
const open = (r) => (same(r[0], r.at(-1)) ? r.slice(0, -1) : r)

// ---------------------------------------------------------------- the river

const river = await fetchJson('river')
const water = []
const islands = []
for (const e of river.elements) {
  for (const r of ringsOf(e)) {
    const cut = dedupe(round(simplify(clipRing(open(r)), 0.00018)))
    if (cut.length >= 3 && area(cut) > 2e-7) water.push(cut)
  }
  for (const r of ringsOf(e, 'inner')) {
    const cut = dedupe(round(simplify(clipRing(open(r)), 0.00018)))
    if (cut.length >= 3 && area(cut) > 6e-7) islands.push(cut)
  }
}
water.sort((a, b) => area(b) - area(a))

// The river's middle line, north to south (the longest chain of its ways: the boats follow it).
const lineData = await fetchJson('line')
const mids = chain(lineData.elements.map((e) => e.geometry.map(pt))).sort((a, b) => length(b) - length(a))
let mid = mids[0]
if (mid[0][1] < mid.at(-1)[1]) mid.reverse()
mid = clipLine(mid).sort((a, b) => length(b) - length(a))[0]
mid = dedupe(round(simplify(mid, 0.0003)))

// ---------------------------------------------------------------- the khlongs, the roads, the parks

function lines(data, tol, min, key = (e) => e.tags['name:en'] || e.tags.name || '') {
  const by = new Map()
  for (const e of data.elements) {
    if (!e.geometry) continue
    const k = key(e)
    if (!by.has(k)) by.set(k, [])
    by.get(k).push(e.geometry.map(pt))
  }
  const out = []
  for (const [name, pieces] of by)
    for (const c of chain(pieces))
      for (const run of clipLine(c)) {
        const l = dedupe(round(simplify(run, tol)))
        if (l.length > 1 && length(l) >= min) out.push({ name, l })
      }
  return out
}

const canals = lines(await fetchJson('canals'), 0.0003, 0.012)

/** A point's distance to a line (degrees). */
function away(p, l) {
  let best = Infinity
  for (let i = 0; i < l.length - 1; i++) {
    const [ax, ay] = l[i]
    const [bx, by] = l[i + 1]
    const len2 = (bx - ax) ** 2 + (by - ay) ** 2 || 1e-12
    const t = Math.max(0, Math.min(1, ((p[0] - ax) * (bx - ax) + (p[1] - ay) * (by - ay)) / len2))
    best = Math.min(best, Math.hypot(p[0] - ax - t * (bx - ax), p[1] - ay - t * (by - ay)))
  }
  return best
}
// The main roads. A big road is two ways side by side (one each way): the second, running along one already kept, is
// left out, so each road is one line.
const roadsAll = lines(await fetchJson('roads'), 0.00035, 0.006).sort((a, b) => length(b.l) - length(a.l))
const roads = []
for (const r of roadsAll) {
  const twin = roads.some((k) => r.l.every((p) => away(p, k.l) < 0.0006))
  if (!twin) roads.push(r)
}

const parkData = await fetchJson('parks')
const parks = []
for (const e of parkData.elements)
  for (const r of ringsOf(e)) {
    const cut = dedupe(round(simplify(clipRing(open(r)), 0.0002)))
    // (About six hectares and up: the parks big enough to show on the board.)
    if (cut.length >= 3 && area(cut) > 5e-6) parks.push({ name: e.tags['name:en'] || e.tags.name || '', r: cut })
  }
parks.sort((a, b) => area(b.r) - area(a.r))

// ---------------------------------------------------------------- write

const fmt = (r) => `[${r.map(([x, y]) => `[${x},${y}]`).join(',')}]`
const text = `// The real city under the Bangkok map, [longitude, latitude] in degrees. Written by scripts/bangkok-map-land.mjs from
// OpenStreetMap (© OpenStreetMap contributors, ODbL): don't edit it by hand. Pure data.
export type LonLat = [number, number]

/** The Chao Phraya's water (and the mouths of the khlongs wide enough to be mapped as water), as rings. */
// prettier-ignore
export const WATER: LonLat[][] = [
${water.map((r) => `  ${fmt(r)},`).join('\n')}
]

/** Islands in that water. */
// prettier-ignore
export const ISLANDS: LonLat[][] = [
${islands.map((r) => `  ${fmt(r)},`).join('\n')}
]

/** The river's middle line, north to south: the boats follow it. */
// prettier-ignore
export const RIVER_LINE: LonLat[] = ${fmt(mid)}

/** The big khlongs (canals), as lines. */
// prettier-ignore
export const KHLONGS: LonLat[][] = [
${canals.map((c) => `  ${fmt(c.l)}, // ${c.name}`).join('\n')}
]

/** The main roads, each as one line. */
// prettier-ignore
export const ROADS: LonLat[][] = [
${roads.map((c) => `  ${fmt(c.l)}, // ${c.name}`).join('\n')}
]

/** The big parks, as rings, biggest first. */
// prettier-ignore
export const PARKS: LonLat[][] = [
${parks.map((c) => `  ${fmt(c.r)}, // ${c.name}`).join('\n')}
]
`
await mkdir(path.dirname(OUT), { recursive: true })
await writeFile(OUT, text)
const n = (ls) => ls.reduce((a, l) => a + l.length, 0)
console.log(`${path.relative(root, OUT)}: water ${water.length} rings (${n(water)} points), islands ${islands.length}, river line ${mid.length}, khlongs ${canals.length} (${n(canals.map((c) => c.l))}), roads ${roads.length} of ${roadsAll.length} (${n(roads.map((c) => c.l))}), parks ${parks.length} (${n(parks.map((c) => c.r))}), ${(text.length / 1024).toFixed(0)} KB`)
